#include <stdio.h>
#include <stdlib.h>

int main() {
    int N, F;
    if (scanf("%d %d", &N, &F) != 2) return 0;

    char **grid = malloc(N * sizeof(char *));
    for (int i = 0; i < N; i++) {
        grid[i] = malloc((N + 1) * sizeof(char));
        scanf("%s", grid[i]);
    }

    int total = N * N;
    int *qr = malloc(total * sizeof(int));
    int *qc = malloc(total * sizeof(int));

    int head = 0, tail = 0;

    if (grid[0][0] - '0' <= F) {
        grid[0][0] = '*';
        qr[tail] = 0;
        qc[tail] = 0;
        tail++;
    }

    int dr[4] = {1, -1, 0, 0};
    int dc[4] = {0, 0, 1, -1};

    while (head < tail) {
        int r = qr[head];
        int c = qc[head];
        head++;

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];

            if (nr >= 0 && nr < N && nc >= 0 && nc < N &&
                grid[nr][nc] != '*' && grid[nr][nc] - '0' <= F) {
                grid[nr][nc] = '*';
                qr[tail] = nr;
                qc[tail] = nc;
                tail++;
            }
        }
    }

    for (int i = 0; i < N; i++) {
        printf("%s\n", grid[i]);
    }

    for (int i = 0; i < N; i++) free(grid[i]);
    free(grid);
    free(qr);
    free(qc);

    return 0;
}
